from grow_helpers import *

def flower_diagram():
    return vis('Selected flower structures and pollen transfer','A simplified flower section labels anther, pollen, stigma, style, ovary and ovule. A pollen-transfer arrow goes from anther to stigma; it does not lead directly to a seed.',[txt(40,20,920,55,'Pollination: pollen reaches a stigma',32,bold=True),rect(472,210,56,160,'#E6F0EA',GREEN),ell(420,150,160,55,'#D1E6D8',GREEN),ell(385,355,230,125,'#E6F0EA',GREEN),ell(450,385,55,55,'#FFE6BA',ORANGE),line(265,350,265,235,GREEN,False),ell(215,195,100,42,'#F3D59C',ORANGE),ell(300,175,20,20,ORANGE,ORANGE),line(325,183,414,173,ORANGE),txt(60,235,260,45,'Anther: makes pollen',26),line(150,231,218,219,DARK,False),txt(675,145,250,45,'Stigma: receives pollen',25),line(580,176,675,176,DARK,False),txt(650,270,260,45,'Style',28),line(530,295,650,295,DARK,False),txt(660,385,260,45,'Ovary',28),line(610,410,660,410,DARK,False),txt(110,405,240,45,'Ovule',28),line(335,430,449,417,DARK,False),txt(70,495,860,42,'Selected structures only; not to scale. Petals are omitted.',25)])

def fertilisation_diagram():
    return vis('After compatible pollen arrives','A pollen grain on the stigma grows a tube through the style towards an ovule. The tube delivers male gametes. A male gamete fuses with an egg cell inside the ovule; the pollen grain itself does not turn into a seed.',[txt(40,18,920,60,'Fertilisation happens after pollination',31,bold=True),rect(450,170,100,180,'#E6F0EA',GREEN),ell(405,125,190,50,'#D1E6D8',GREEN),ell(360,340,280,145,'#E6F0EA',GREEN),ell(465,110,28,28,'#F3D59C',ORANGE),line(480,145,480,320,ORANGE,False),line(480,320,510,388,ORANGE),ell(485,375,82,72,'#FFE6BA',ORANGE),ell(519,398,22,22,'#EFAE7B',ORANGE),txt(45,155,300,70,'Pollen grain grows\na pollen tube',27),line(345,196,452,196,DARK,False),txt(655,185,280,105,'Male gamete\ntravels through\nthe tube',27),line(550,253,650,253,DARK,False),txt(45,355,285,110,'Egg cell\ninside an ovule',28),line(335,418,518,410,DARK,False),txt(675,360,255,100,'Gametes fuse:\nfertilisation',27),txt(70,500,860,40,'One key fusion is shown; advanced double-fertilisation detail omitted.',24)])

def flower():
    d=base('grow_flower_to_seed','The flower-to-seed investigation','Trace pollen, fertilisation and the formation of seeds','Describe pollination, fertilisation and seed formation as different connected processes.',3,['Identify flower, stem and leaf.','Know that reproduction produces new individuals.'],['Trace pollen from anther to stigma.','Distinguish pollen transfer from fusion of gametes.','Explain that a fertilised ovule develops into a seed.'],[('pollen','Grains that carry the male reproductive cells in flowering plants.'),('pollination','Transfer of pollen from anther to stigma.'),('stigma','The flower part that receives pollen.'),('ovule','A structure in the ovary containing an egg cell; it can develop into a seed.'),('fertilisation','Fusion of male and female gametes.'),('gamete','A reproductive cell such as an egg cell.')],['Shared orchard evidence, chosen route, pencils; optional paper pollen tokens.'],['Use diagrams or paper tokens, not real pollen.','Explain that our example follows ordinary sexual reproduction in a flowering plant.'],['No pollen blowing, plant tasting or flower dissection is required; paper route avoids pollen allergy exposure.'],'Trace paper pollen and stage cards using the supplied observations. No live plant, internet or completed growing trial is needed.',[('Pollination is the same as fertilisation.','Pollination transfers pollen; fertilisation is gamete fusion later in the ovule.','Ask where each process occurs.'),('A pollen grain simply becomes a seed.','A fertilised ovule develops into a seed; the pollen supplies male gametes.','Ask which structure develops into the seed.'),('Every pollen grain landing anywhere on a plant makes a seed.','Pollen must reach a suitable stigma; further processes and suitable conditions are needed.','Ask whether pollen on a leaf counts as pollination.')],['Order named stages using prompts and label the main route.','Explain the three processes and interpret an orchard evidence set.','Evaluate a pollination guarantee and explain limits of the observations.'],[POLLEN])
    v1=flower_diagram();v2=fertilisation_diagram()
    v3=vis('Two structures develop after fertilisation','Two parallel developmental links: fertilised ovule develops into seed; ovary develops into fruit. The pollen grain is not shown becoming a seed.',[txt(40,25,920,55,'After fertilisation: identify the structure',31,bold=True),rect(75,150,320,110),txt(95,180,280,60,'Fertilised ovule',30),rect(610,150,315,110),txt(630,180,275,60,'Seed',31),line(395,205,610,205),rect(75,345,320,110),txt(95,375,280,60,'Ovary',31),rect(610,345,315,110),txt(630,375,275,60,'Fruit',31),line(395,400,610,400),txt(70,493,860,42,'A seed contains a young plant embryo; fruit surrounds seeds.',25)])
    ev=[('A • Transfer event','A bee carries pollen from an anther to a stigma of a suitable flower. This is pollen transfer, not the fusion event.'),('B • Inside the flower','After compatible pollen arrives, a pollen tube can grow. A male gamete can reach an egg cell in an ovule and fuse with it.'),('C • Development','After successful fertilisation, an ovule develops into a seed; the ovary develops into fruit. Other conditions also affect success.'),('D • Wrong destination','Pollen is seen on a leaf. No pollen is seen on the stigma in this record. The record does not show pollination.'),('E • Incomplete evidence','Pollen is seen on a stigma. The inside of the ovule has not been observed. Pollen transfer alone does not prove fertilisation occurred.'),('F • Model boundary','This model follows sexual reproduction in a flowering plant. It omits detailed cell structures and time scales; no class growing experiment took place.')]
    d['slides']=[slide('Opening',2,'A pollen delivery mystery',['Pollen reaches a plant. Does that guarantee a seed?','We will follow the destination and the next processes.'],'Invite predictions without requiring existing terminology. Explain that paper evidence gives the whole investigation.'),slide('Retrieval',3,'Recover the plant words',['R1. Name a flowering-plant part.','R2. What can a seed grow into in suitable conditions?','R3. Does reproduction mean the parent grows taller?'],'Valid part; new plant; no, reproduction makes offspring, whereas growth increases size/development of an individual.'),slide('I do',8,'I trace the correct delivery destination',['Anthers produce pollen.','A stigma receives pollen.','Pollination names this transfer.'],'Think aloud: I place my token on the anther, then move it to the stigma. A landing on a leaf would not complete this defined transfer. This selected diagram omits petals and exact scale.',visual=v1),slide('I do',0,'I distinguish the event inside the ovule',['Compatible pollen can grow a tube.','A male gamete reaches an egg cell.','Their fusion is fertilisation.'],'Shared I do time. Think aloud: The transfer has already happened; now I describe a different event. The male gamete travels through a tube; the egg is in an ovule within the ovary. Advanced double fertilisation is omitted.',visual=v2),slide('I do',0,'I name what develops into a seed',['The fertilised ovule develops into a seed.','The ovary develops into fruit.','A pollen grain does not turn into the seed.'],'Shared I do time. Trace each independent arrow. Ordinary botanical fruits include pods; fruit here is a plant structure, not just a sweet food.',visual=v3),slide('We do',8,'Orchard evidence desk',['Use records A–F.','W1. Which record shows pollination?','Which record shows only pollen in the wrong place?'],'A shows transfer to stigma; D records pollen on leaf. Ask pupils to place or point to the appropriate destination on a diagram.',table=table(['Observed record','What can we establish?'],[['A: anther → suitable stigma','Pollen transfer'],['D: pollen on leaf','Wrong destination in this record'],['E: pollen on stigma; inside unseen','Transfer, but fusion not observed']])),slide('We do',0,'Audit the missing step',['W2. Put A, B and C in process order.','Explain what changes from transfer to fusion to development.'],'A pollination→B fertilisation→C seed/fruit development. A bee does not carry ready-made seeds into the ovary.'),slide('We do',0,'What does the evidence prove?',['W3. Record E has pollen on a stigma.','Can the observer claim fertilisation definitely happened?','Give the strongest claim that the record supports.'],'No; pollen transfer is seen, not gamete fusion. State that the record supports pollination but does not establish later success.',reveal='The record shows pollen on a stigma. It does not by itself prove fertilisation or a mature seed.'),slide('Hinge',3,'Which structure becomes a seed?',['Choose the scientifically accurate explanation.'],'A false pollen/seed confusion; B correct; C false leaves not seed precursors here.',options=opts([('The pollen grain simply changes into a seed.',False,'Pollen supplies male gametes; the ovule develops into the seed.'),('A fertilised ovule develops into a seed.',True,'This distinguishes reproductive cells from the structure that develops.'),('A leaf changes into every seed.',False,'In this model, seeds develop from ovules inside the ovary.')]))]
    common_tail(d,['Choose one response route.','Trace the flower-to-seed sequence.','Use records to separate observation from inference.'],['Name the destination: anther to stigma.','Distinguish transfer, fusion and development.','State what the observer has actually seen.'],['Share one accurate arrow or process label.','Check it against the source cards.','Improve a seed or fertilisation claim.'],['E1. What is pollination?','E2. How is fertilisation different?','E3. What develops into a seed?'],'Transfer anther→stigma; gamete fusion; fertilised ovule. E4 on pupil page asks why pollen on leaf is insufficient.')
    d['pupilPages']=[page('1 • Shared evidence: orchard records','These are constructed observation scenarios, not results from a class experiment.',[cards(ev),response('W1. Compare records A and D. Which shows pollination?',2),response('W2. Order A, B and C and name the three processes.',2),response('W3. What can record E establish, and what remains unobserved?',2)]),page('2 • Supported route: follow the pollen','Word bank: anther / stigma / ovule / pollination / fertilisation.',[response('S1. Complete the transfer: pollen moves from an ____ to a ____ .',3),choices('S2. What is that transfer called?',['Pollination','Fertilisation']),response('S3. Complete: The fusion of a male gamete and an egg cell is ____ .',3),choices('S4. Which develops into a seed?',['A fertilised ovule','A pollen grain on a leaf']),response('S5. Order: seed develops / pollen reaches stigma / gametes fuse. Explain one arrow.',4)]),page('3 • Standard route: process investigator','Use source cards A–F.',[tb(['Process','What happens?'],[['Pollination',''],['Fertilisation',''],['Seed formation','']]),response('N1. Complete the process table.',2),response('N2. Trace pollen’s role from anther to a male gamete reaching an egg cell. Name the ovule.',4),response('N3. Explain why pollen on a leaf is not evidence of pollination.',3),response('N4. Record E shows pollen on a stigma. Explain what is known and what cannot yet be claimed.',3)]),page('4 • Stretch route: audit the orchard claim','Use precise biological structures and bounded evidence.',[response('T1. Explain the full sequence from pollen transfer to seed formation. Include anther, stigma, gamete and ovule.',5),response('T2. Repair “Bees carry seeds to a flower, then pollen becomes the fruit”.',4),response('T3. Does observing pollen on a stigma guarantee a mature seed? Explain two later requirements or uncertainties.',4),response('T4. Design a record that separates observation of pollen arrival from later seed development. What would each observation establish?',4)]),page('5 • Exit and reflection','Use a short explanation or labelled route.',[response('E1. What is pollination?',3),response('E2. How is fertilisation different?',3),response('E3. What develops into a seed, and what develops into fruit?',3),response('E4. Why does pollen on a leaf not establish pollination?',3),response('Reflection. Which later stage would you investigate next?',3)])]
    d['answers']=[ans('R1–R3','R1 valid plant part. R2 a new plant in suitable conditions. R3 no; reproduction produces offspring, whereas growth develops an individual.'),ans('W1–W3','W1 A shows pollination; D has pollen on a leaf, not the required stigma. W2 A→B→C: transfer, fusion, development. W3 pollen on stigma is observed; successful fusion and later seed development are not established by that observation alone.'),ans('Hinge A–C','A incorrect: pollen does not become seed. B correct. C incorrect: ovules, not leaves, develop into seeds in this model.'),ans('S1–S5','S1 anther; stigma. S2 pollination. S3 fertilisation. S4 fertilised ovule. S5 pollen reaches stigma→gametes fuse→seed develops; any accurate arrow explanation.'),ans('N1–N4','N1 pollination: anther-to-stigma transfer; fertilisation: fusion of male/female gametes; seed formation: fertilised ovule develops. N2 pollen arrives at stigma, tube grows and delivers male gamete to egg cell in ovule. N3 leaf is not stigma. N4 transfer is evidenced, not later fertilisation or mature seed success.'),ans('T1–T4','T1 accurate connected sequence, with distinct transfer and fusion. T2 bees can transfer pollen, not plant seeds into ovaries; ovules develop into seeds and ovaries into fruit. T3 compatible pollen, tube growth/gamete delivery, fertilisation and suitable development conditions remain relevant; choose two without requiring technical detail. T4 separate dated records for pollen arrival on stigma and later seed formation, with a matched observation method; arrival supports pollination, later mature seeds support successful development in the sexual example. A record should not claim unobserved cellular detail.'),ans('E1–E4 / assessment','E1 transfer anther→stigma. E2 fusion of gametes. E3 ovule→seed, ovary→fruit. E4 incorrect destination. Secure: clear distinction of the three processes and correct structure development. Re-teach by assigning a different verb to each arrow. Reflection has no fixed choice.')]
    interactive(d,'Orchard audit: predict the process',[( 'Where must pollen arrive for pollination?', [('A stigma.',True,'Pollination transfers pollen from anther to stigma.'),('Any leaf surface.',False,'Pollen on a leaf does not complete the defined transfer.')],'Move the paper or screen token to the correct destination for W1.'),('What event is fertilisation?',[('Male and female gametes fuse.',True,'This occurs after pollen transfer in the ovule.'),('A bee lands on a petal.',False,'A landing is not evidence of gamete fusion.')],'Use W2 to distinguish the events.'),('Which conclusion follows from pollen on a stigma alone?',[('Transfer has occurred; later seed success remains uncertain.',True,'Arrival alone does not show every later stage.'),('A mature seed is guaranteed.',False,'Fertilisation and development still have to succeed.')],'State a bounded conclusion for W3.')])
    finish(d,['This lesson follows ordinary sexual reproduction in flowering plants; it does not claim every plant seed in nature requires fertilisation. Asexual seed formation is a later teacher nuance.','The interactive uses the same constructed records as W1–W3. Paper pollen tokens provide a complete alternative without exposure to real pollen.'])

def reproduction():
    d=base('grow_plant_reproduction_studio','The plant reproduction strategy studio','Compare gamete fusion with runners and cuttings','Distinguish sexual and asexual plant reproduction using process evidence rather than the number of visible parent plants.',4,['Describe pollination and fertilisation.','Know that offspring inherit genetic information.'],['Identify whether gamete fusion occurs in a case.','Describe a runner or cutting as an asexual route.','Explain why sexual reproduction can involve one self-pollinating plant.'],[('sexual reproduction','Reproduction involving fusion of gametes.'),('asexual reproduction','Reproduction without gamete fusion.'),('runner','A horizontal stem that can produce a new plant at a node.'),('cutting','A piece of a parent plant used to grow a new plant.'),('clone','An offspring with the same inherited genetic information as its source, apart from changes such as mutations.'),('variation','Differences among individuals; genes and environment can contribute.')],['Plant case cards, selected route, pencils; optional paper runner model.'],['Use the case’s stated reproductive process, not just appearance or number of plants.','No live cutting or rooting chemical is needed.'],['Use paper models; no plant tasting, cutting tools or hormone powder.'],'All decisions use supplied cases and diagrams. A live propagation experiment is not required or claimed completed.',[('Sexual reproduction always needs two separate parent plants.','Some flowers can self-pollinate and self-fertilise; gamete fusion is still sexual reproduction.','Ask whether gametes fuse in the case.'),('Every seed must be sexual and every clone looks identical.','Some plants form asexual seeds; environment can alter the appearance of genetically similar plants.','Ask what process is actually stated.'),('Asexual offspring can never vary at all.','They are usually genetically very similar clones, but mutations and environmental effects can produce differences.','Ask whether different growth conditions could change height.')],['Sort stated gamete-fusion cases and explain one runner.','Compare processes and choose a nursery plan using evidence.','Evaluate self-fertilisation, clone and all-seeds claims.'],[POLLEN,ASEX,source('RHS: How plants reproduce','https://www.rhs.org.uk/advice/understanding-plants/how-plants-reproduce','Checked September 2026. Sexual and clonal propagation overview; plants may use more than one reproductive strategy.')])
    v1=boxes('Sexual reproduction: the defining event',['Male gamete','Fusion with\nfemale gamete','Offspring\nwith inherited genes'],'Gametes may come from different plants\nor from one self-fertile plant.')
    v2=vis('Strawberry runner: new plant from a stem','An original strawberry plant is connected by a horizontal runner to a rooted daughter plant. Both are shown above the same ground line; no gamete fusion is required in this vegetative route.',[txt(40,20,920,55,'A runner can produce a daughter plant',31,bold=True),line(50,385,950,385,DARK,False),line(240,385,240,245,GREEN,False),ell(155,230,95,45,'#CBE0D5',GREEN),ell(245,260,100,45,'#CBE0D5',GREEN),line(240,360,720,360,GREEN,False),line(720,385,720,270,GREEN,False),ell(640,270,90,42,'#CBE0D5',GREEN),ell(725,290,90,42,'#CBE0D5',GREEN),line(240,385,205,465,GREEN,False),line(240,385,280,455,GREEN,False),line(720,385,688,450,GREEN,False),line(720,385,754,453,GREEN,False),txt(100,140,280,55,'Parent plant',30),txt(580,170,280,55,'Daughter plant',30),txt(355,290,260,45,'Runner: a stem',27),txt(70,492,860,45,'Vegetative growth from the parent; no gamete fusion here.',25)])
    v3=vis('Genes and environment are different influences','Two rooted cuttings from the same parent are drawn with different heights under different growth conditions. The comparison illustrates that clonal genetic similarity does not guarantee identical appearance.',[txt(40,20,920,55,'Clones need not look identical',32,bold=True),rect(75,140,390,305),rect(535,140,390,305),txt(90,155,360,70,'Same parent cutting\ncondition A',28),txt(550,155,360,70,'Same parent cutting\ncondition B',28),line(100,405,440,405,DARK,False),line(560,405,900,405,DARK,False),line(270,405,270,270,GREEN,False),line(730,405,730,330,GREEN,False),ell(220,285,60,30,'#CBE0D5',GREEN),ell(270,320,65,30,'#CBE0D5',GREEN),ell(688,343,55,28,'#CBE0D5',GREEN),txt(70,485,860,55,'Illustrative model: genes and growth conditions both affect traits.',25)])
    ev=[('A • Crossed flowers','Pollen from one pea plant reaches another. A male and female gamete fuse before the seed develops.'),('B • Self-fertile flower','A flower receives its own plant’s pollen. Male and female gametes fuse before a seed develops.'),('C • Strawberry runner','A horizontal stem grows from a parent. It roots at a node and forms a daughter plant without gamete fusion.'),('D • Mint cutting','A piece of a parent stem roots and grows into a new plant. No gamete fusion occurs in this route.'),('E • Nursery brief','A fictional nursery wants to preserve a parent mint plant’s inherited features. It can use cuttings; growth conditions still need care.'),('F • Limits card','Clones usually share inherited information, apart from changes such as mutations. Conditions affect appearance. Some plants can make seeds without fertilisation; identify the stated process.')]
    d['slides']=[slide('Opening',2,'One visible parent: one answer?',['A new plant grows near one parent.','Can you identify the reproduction type from that alone?'],'No: need process evidence. The lesson’s central question is whether gametes fuse, not merely counting visible plants.'),slide('Retrieval',3,'Recover the fusion event',['R1. What is fertilisation?','R2. What develops into a seed after fertilisation?','R3. Is growth of one plant the same as producing offspring?'],'Gamete fusion; fertilised ovule; no. Do not treat every natural seed as necessarily sexual.'),slide('I do',8,'I look for gamete fusion',['Fusion identifies sexual reproduction.','Gametes can come from one self-fertile plant.','Two separate plants are not the defining rule.'],'Think aloud with case B: I see only one parent plant, but the record says gametes fuse. Therefore it is sexual reproduction. A self-fertile plant can supply both gametes.',visual=v1),slide('I do',0,'I trace the runner route',['The new plant grows from a parent stem.','No gametes fuse in this runner route.','This is asexual reproduction.'],'Shared I do time. Trace runner from parent to rooted node. The runner is a stem, not a root stretching between unrelated plants. It can remain attached during early growth.',visual=v2),slide('I do',0,'I separate genetic similarity from appearance',['A cutting can produce a clone of its source.','Conditions can affect size and appearance.','“Clone” does not mean every visible feature is fixed.'],'Shared I do time. Use illustrative growth model, not measured trial data. Explain that mutation is a possible genetic change; supported pupils need only avoid the never-varies claim.',visual=v3),slide('We do',8,'Nursery case conference',['W1. Sort A–D using gamete fusion.','Give the evidence phrase that decides each case.','Do not count parent plants alone.'],'A/B sexual; C/D asexual. Pupils move labels or vote privately, then justify using the case wording.',table=table(['Case','Key evidence'],[['A: crossed flowers','Gametes fuse'],['B: self-fertile flower','Gametes fuse'],['C: runner','No gamete fusion'],['D: cutting','No gamete fusion']])),slide('We do',0,'Choose a plan for the nursery',['W2. The nursery wants inherited mint features retained.','Recommend the stated cutting route or a new cross.','Give one reason and one condition to control.'],'Cuttings preserve the source’s inherited features more directly; seed crosses can introduce genetic variation. Keep suitable light/water/temperature consistent; clones do not guarantee identical growth or immunity.'),slide('We do',0,'Challenge the shortcut rules',['W3. Repair “one parent always means asexual”.','Then repair “all clones always look identical”.'],'Case B contradicts the first; environment/mutation limits second. Accept concise bounded explanations.',reveal='Use the fusion evidence. A self-fertile plant can reproduce sexually; clone appearance can vary.'),slide('Hinge',3,'A flower self-fertilises',['Its male and female gametes fuse. Which route is this?'],'Sexual because fusion occurs; not defined by number of separate plants; not ordinarygrowth only.',options=opts([('Sexual reproduction.',True,'Gamete fusion is the defining event, even with one parent plant.'),('Asexual because only one parent plant is visible.',False,'Counting plants misses the fusion event.'),('No reproduction, only taller growth.',False,'A new offspring develops after fertilisation.')]))]
    common_tail(d,['Choose one route.','Use the stated process to classify each case.','Explain a nursery decision and its limits.'],['Underline “gametes fuse” or “no fusion”.','Name runner or cutting when relevant.','Separate genes from growth conditions.'],['Share one classification and reason.','Check a broad rule against the case cards.','Improve an absolute clone claim.'],['E1. What distinguishes sexual reproduction?','E2. Give one asexual plant method.','E3. Can self-fertilisation be sexual? Explain.'],'Fusion; runner/cutting; yes, gametes fuse. E4 asks why clones may look different.')
    d['pupilPages']=[page('1 • Shared evidence: nursery cases','Cases are constructed teaching examples using the stated biological processes.',[cards(ev),response('W1. Sort A–D into sexual/asexual and cite the deciding phrase.',2),response('W2. Recommend a route for the mint nursery and one condition to control.',2),response('W3. Repair the one-parent and identical-clone rules.',2)]),page('2 • Supported route: find the fusion','Use page 1. Word bank: sexual / asexual / gametes / runner.',[choices('S1. In case B, gametes fuse. Is this sexual or asexual?',['Sexual','Asexual']),choices('S2. A strawberry runner grows a daughter plant without fusion. Is this sexual or asexual?',['Sexual','Asexual']),response('S3. Complete: Sexual reproduction involves ____ fusing. A ____ can form a new plant without that fusion.',3),response('S4. Which method could retain the mint parent’s inherited features: cutting or a new cross? Explain.',3),response('S5. Give one reason two clones might look different.',3)]),page('3 • Standard route: nursery decision','Use the process evidence, not a visual parent count.',[tb(['Case','Route','Evidence phrase'],[['A','',''],['B','',''],['C','',''],['D','','']]),response('N1. Complete the case table.',2),response('N2. Explain why case B is sexual despite one parent plant.',3),response('N3. Recommend a method for the mint brief. Give a reason and one growth condition to control.',3),response('N4. Repair “clones always look identical”.',3)]),page('4 • Stretch route: test the definitions','Avoid all/never claims unsupported by the stated cases.',[response('T1. Compare sexual and asexual reproduction using fusion, inherited information and one named method.',5),response('T2. Explain why “two parents versus one” is an unreliable complete definition for plants.',4),response('T3. A plant forms seeds without gamete fusion. Which reproduction category fits the stated evidence? Explain.',4),response('T4. Evaluate a nursery promise: “Every cutting will look identical and resist every disease.” Give a better claim and one practical limitation.',4)]),page('5 • Exit and reflection','Short reasons matter more than labels alone.',[response('E1. What event defines sexual reproduction?',3),response('E2. Describe one asexual plant method.',3),response('E3. Can one self-fertile plant reproduce sexually? Explain.',3),response('E4. Why might genetically similar clones look different?',3),response('Reflection. Which nursery question needs more evidence?',3)])]
    d['answers']=[ans('R1–R3','Gamete fusion; fertilised ovule; growth develops one individual while reproduction produces offspring.'),ans('W1–W3','A/B sexual because gametes fuse; C/D asexual because no fusion. W2 cutting for retaining source genetic features, with controlled suitable growth conditions. W3 self-fertilisation is a one-parent sexual case; clones can differ through environment and sometimes mutation.'),ans('Hinge A–C','A correct; B incorrectly counts visible parents; C ignores production of offspring.'),ans('S1–S5','S1 sexual. S2 asexual. S3 gametes; runner. S4 cutting, because it develops vegetatively from the source and usually retains its genetic information. S5 different environment or mutation; an accurate example such as different light is sufficient.'),ans('N1–N4','A sexual/fusion; B sexual/fusion; C asexual/no fusion via runner; D asexual/no fusion via cutting. N2 gamete fusion defines the route. N3 cutting plus retained inherited features and relevant control. N4 genetically similar plants can respond differently to growth conditions; mutation can also alter inherited information.'),ans('T1–T4','T1 sexual uses fusion and typically produces genetic variation; asexual has no fusion and usually produces clones, e.g. runner/cutting. T2 self-fertilisation can use one plant yet remain sexual. T3 asexual seed formation according to the stated lack of fusion; this prevents treating all seeds as sexual. T4 cuttings usually retain source genes but appearance, establishment and disease outcomes depend on more than that; use suitable conditions and monitor health without guarantees.'),ans('E1–E4 / assessment','Fusion; accurate runner/cutting description; yes through gamete fusion; conditions or mutation may differ. Secure: correct process definition applied to self-fertilisation and vegetative cases, plus a bounded clone claim. Re-teach classification by highlighting the fusion evidence. Reflection accepts a relevant uncertainty.')]
    interactive(d,'Nursery studio: choose from process evidence',[( 'Case B uses one self-fertile plant and gamete fusion. Which route?', [('Sexual.',True,'The fusion event defines it.'),('Asexual because one plant is visible.',False,'One plant can supply both gametes.')],'Explain the evidence phrase for W1.'),('A daughter plant roots from a strawberry runner. What matters?',[('No gametes fuse in this route.',True,'Vegetative growth from the parent makes this an asexual example.'),('A new flower must be fertilised first.',False,'The stated runner route does not require fertilisation.')],'Trace the runner stem, then justify the category.'),('Can the nursery promise identical appearance in every condition?',[('No; growth conditions and sometimes mutations can cause differences.',True,'Genetic similarity is not a guarantee of identical appearance.'),('Yes; clones can never differ.',False,'The absolute claim ignores environment and genetic changes.')],'Improve the nursery claim for W2–W3.')])
    finish(d,['The defining distinction is gamete fusion. Self-fertilisation remains sexual even if one plant supplies both gametes. Do not teach all seeds as universally sexual; optional asexual seed formation is explicitly signposted.','Paper runner and cutting cards support the same interactive decisions. A propagation practical would require separate ongoing care; this lesson does not claim roots appear within 40 minutes.'])

